ALTER POLICY "Ended crew media keeps owner access" ON storage.objects USING (bucket_id <> 'chat-photos' OR owner=auth.uid() OR owner_id=auth.uid()::text OR EXISTS (SELECT 1 FROM public.check_ins c WHERE (c.photo_url=storage.objects.name OR c.photo_url || '.poster.jpg'=storage.objects.name) AND public.crew_is_active(c.group_id) AND public.is_group_member(c.group_id,auth.uid())) OR EXISTS (SELECT 1 FROM public.post_comments c JOIN public.daily_posts p ON p.id=c.post_id WHERE c.media_url=storage.objects.name AND public.crew_is_active(p.group_id) AND public.is_group_member(p.group_id,auth.uid())) OR EXISTS (SELECT 1 FROM public.group_messages m WHERE m.image_url=storage.objects.name AND public.crew_is_active(m.group_id) AND public.is_group_member(m.group_id,auth.uid())) OR EXISTS (SELECT 1 FROM public.groups g WHERE g.id::text=(storage.foldername(storage.objects.name))[1] AND g.ended_at IS NULL AND public.is_group_member(g.id,auth.uid())));
CREATE TRIGGER active_crew_session_start BEFORE INSERT ON public.workout_sessions FOR EACH ROW EXECUTE FUNCTION public.guard_active_crew_write();
CREATE TRIGGER active_crew_session_reopen BEFORE UPDATE ON public.workout_sessions FOR EACH ROW WHEN (NEW.status='active' AND OLD.status IS DISTINCT FROM NEW.status) EXECUTE FUNCTION public.guard_active_crew_write();